def single_number(nums):
    x = 0
    for v in nums:
        x ^= v          # pairs cancel: v ^ v == 0
    return x

def hamming_total(nums):
    total = 0
    for bit in range(32):
        ones = sum((v >> bit) & 1 for v in nums)
        total += ones * (len(nums) - ones)
    return total
